ALTER TABLE "Contract" ADD COLUMN "spendLimit" DOUBLE PRECISION, ADD COLUMN "autoRenew" BOOLEAN NOT NULL DEFAULT false, ADD COLUMN "renewalNoticeDays" INTEGER NOT NULL DEFAULT 90;
ALTER TABLE "BudgetCategory" ADD COLUMN "alertThreshold" DOUBLE PRECISION NOT NULL DEFAULT 80, ADD COLUMN "carryForward" BOOLEAN NOT NULL DEFAULT false;
CREATE TABLE "WarehouseBin" ("id" TEXT NOT NULL, "warehouseId" TEXT NOT NULL, "code" TEXT NOT NULL, "name" TEXT NOT NULL, "capacity" DOUBLE PRECISION NOT NULL DEFAULT 0, "status" TEXT NOT NULL DEFAULT 'Available', "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "WarehouseBin_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "WarehouseBin_warehouse_code_key" ON "WarehouseBin" ("warehouseId", "code");
CREATE TABLE "PutawayTask" ("id" TEXT NOT NULL, "taskId" TEXT NOT NULL, "goodsReceiptId" TEXT NOT NULL, "inventoryId" TEXT, "binId" TEXT NOT NULL, "quantity" DOUBLE PRECISION NOT NULL, "status" TEXT NOT NULL DEFAULT 'Open', "assignedTo" TEXT, "completedAt" TIMESTAMP(3), "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "PutawayTask_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "PutawayTask_taskId_key" ON "PutawayTask" ("taskId");
CREATE TABLE "FulfillmentTask" ("id" TEXT NOT NULL, "orderId" TEXT NOT NULL, "status" TEXT NOT NULL DEFAULT 'Pick Pending', "lines" JSONB NOT NULL, "pickedAt" TIMESTAMP(3), "packedAt" TIMESTAMP(3), "shippedAt" TIMESTAMP(3), "assignedTo" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "FulfillmentTask_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "FulfillmentTask_orderId_key" ON "FulfillmentTask" ("orderId");
CREATE TABLE "CycleCount" ("id" TEXT NOT NULL, "countId" TEXT NOT NULL, "warehouseId" TEXT NOT NULL, "binId" TEXT, "inventoryId" TEXT, "expectedQty" DOUBLE PRECISION NOT NULL, "countedQty" DOUBLE PRECISION, "variance" DOUBLE PRECISION, "status" TEXT NOT NULL DEFAULT 'Open', "countedBy" TEXT, "approvedBy" TEXT, "countedAt" TIMESTAMP(3), "approvedAt" TIMESTAMP(3), "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "CycleCount_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "CycleCount_countId_key" ON "CycleCount" ("countId");
CREATE TABLE "StockAdjustment" ("id" TEXT NOT NULL, "adjustmentId" TEXT NOT NULL, "inventoryId" TEXT NOT NULL, "quantity" DOUBLE PRECISION NOT NULL, "reason" TEXT NOT NULL, "status" TEXT NOT NULL DEFAULT 'Pending Approval', "createdBy" TEXT NOT NULL, "approvedBy" TEXT, "approvedAt" TIMESTAMP(3), "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "StockAdjustment_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "StockAdjustment_adjustmentId_key" ON "StockAdjustment" ("adjustmentId");
CREATE TABLE "ContractVersion" ("id" TEXT NOT NULL, "contractId" TEXT NOT NULL, "version" INTEGER NOT NULL, "summary" TEXT, "documentUrl" TEXT, "effectiveFrom" TIMESTAMP(3) NOT NULL, "effectiveTo" TIMESTAMP(3), "status" TEXT NOT NULL DEFAULT 'Draft', "createdBy" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "ContractVersion_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "ContractVersion_contract_version_key" ON "ContractVersion" ("contractId", "version");
CREATE TABLE "ContractObligation" ("id" TEXT NOT NULL, "contractId" TEXT NOT NULL, "title" TEXT NOT NULL, "description" TEXT, "dueDate" TIMESTAMP(3) NOT NULL, "owner" TEXT, "status" TEXT NOT NULL DEFAULT 'Open', "completedAt" TIMESTAMP(3), "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "ContractObligation_pkey" PRIMARY KEY ("id"));
CREATE TABLE "ContractComplianceDocument" ("id" TEXT NOT NULL, "contractId" TEXT NOT NULL, "documentType" TEXT NOT NULL, "documentUrl" TEXT, "expiresAt" TIMESTAMP(3) NOT NULL, "status" TEXT NOT NULL DEFAULT 'Valid', "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "ContractComplianceDocument_pkey" PRIMARY KEY ("id"));
CREATE TABLE "BudgetReservation" ("id" TEXT NOT NULL, "budgetId" TEXT NOT NULL, "requisitionId" TEXT NOT NULL, "amount" DOUBLE PRECISION NOT NULL, "status" TEXT NOT NULL DEFAULT 'Reserved', "createdBy" TEXT NOT NULL, "releasedAt" TIMESTAMP(3), "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "BudgetReservation_pkey" PRIMARY KEY ("id"));
CREATE INDEX "BudgetReservation_budget_status_idx" ON "BudgetReservation" ("budgetId", "status");
CREATE TABLE "BudgetTransferRequest" ("id" TEXT NOT NULL, "transferId" TEXT NOT NULL, "fromBudgetId" TEXT NOT NULL, "toBudgetId" TEXT NOT NULL, "amount" DOUBLE PRECISION NOT NULL, "reason" TEXT NOT NULL, "status" TEXT NOT NULL DEFAULT 'Pending Approval', "requestedBy" TEXT NOT NULL, "approvedBy" TEXT, "approvedAt" TIMESTAMP(3), "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "BudgetTransferRequest_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "BudgetTransferRequest_transferId_key" ON "BudgetTransferRequest" ("transferId");
CREATE TABLE "SupplierComplianceCheck" ("id" TEXT NOT NULL, "supplierId" TEXT NOT NULL, "documentType" TEXT NOT NULL, "documentUrl" TEXT, "expiresAt" TIMESTAMP(3), "status" TEXT NOT NULL DEFAULT 'Pending', "checkedAt" TIMESTAMP(3), "checkedBy" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "SupplierComplianceCheck_pkey" PRIMARY KEY ("id"));
CREATE TABLE "SupplierRiskAssessment" ("id" TEXT NOT NULL, "supplierId" TEXT NOT NULL, "riskScore" DOUBLE PRECISION NOT NULL DEFAULT 0, "sanctionsStatus" TEXT NOT NULL DEFAULT 'Not Checked', "financialHealth" TEXT NOT NULL DEFAULT 'Unknown', "concentrationScore" DOUBLE PRECISION NOT NULL DEFAULT 0, "notes" TEXT, "assessedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "assessedBy" TEXT NOT NULL, CONSTRAINT "SupplierRiskAssessment_pkey" PRIMARY KEY ("id"));
